/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.bs4;import java.util.Arrays;public class B4grid extends B4box<B4grid> {	public static final String container = "container";	public static final String containerFluid = "container-fluid";	private int[] numbers = null;	public B4grid device(int... numbers) {		this.numbers = B4col.numbers(numbers);		return this;	}	public B4grid device(String device) {		this.numbers = B4col.numbers(device);		return this;	}	public B4grid container() {		super.cssClass(container);		return this;	}	public B4grid container(boolean fluid) {		super.cssClass(fluid ? containerFluid : container);		return this;	}	@Override	public void build() {		if (this.numbers != null && super.count() > 0) {			super.getContents().forEach(c -> {				if (c instanceof B4row) {					B4row row = (B4row) c;					if (row.getNumbers() == null) {						row.setNumbers(Arrays.copyOf(this.numbers, this.numbers.length));					}				}			});		}		super.build();	}	public int[] getNumbers() {		return numbers;	}	public void setNumbers(int[] numbers) {		this.numbers = numbers;	}	}